const settings = $('Set Watchtower Parameters').first().json;
const backendInfo = $('Select Least Busy QPU').first().json;
const props = $input.first().json;

const backendName = backendInfo.leastBusy;
const qubitProps = Array.isArray(props.qubits) ? props.qubits : [];
const nQubits = qubitProps.length;
const czCeiling = Number(settings.maxAcceptableCzError) || 0.1;

if (!backendName) { throw new Error('The least-busy lookup returned no backend name.'); }
if (nQubits === 0) { throw new Error('Calibration for ' + backendName + ' contained no qubit properties.'); }

function metricFor(index, name) {
  const list = qubitProps[index] || [];
  let value = null;
  for (const entry of list) {
    if (entry && entry.name === name && typeof entry.value === 'number') { value = entry.value; }
  }
  return value;
}

const links = [];
for (const gate of (props.gates || [])) {
  if (!gate || gate.gate !== 'cz') { continue; }
  if (!Array.isArray(gate.qubits) || gate.qubits.length !== 2) { continue; }
  const control = gate.qubits[0];
  const target = gate.qubits[1];
  if (control >= nQubits || target >= nQubits) { continue; }
  let czError = null;
  for (const p of (gate.parameters || [])) {
    if (p && p.name === 'gate_error' && typeof p.value === 'number') { czError = p.value; }
  }
  const roControl = metricFor(control, 'readout_error');
  const roTarget = metricFor(target, 'readout_error');
  if (czError === null || roControl === null || roTarget === null) { continue; }
  if (czError >= czCeiling) { continue; }
  links.push({
    controlQubit: control,
    targetQubit: target,
    czError: czError,
    readoutErrorControl: roControl,
    readoutErrorTarget: roTarget,
    t1Control: metricFor(control, 'T1'),
    t2Control: metricFor(control, 'T2'),
    t1Target: metricFor(target, 'T1'),
    t2Target: metricFor(target, 'T2'),
    linkScore: czError + roControl + roTarget
  });
}

if (links.length === 0) {
  throw new Error('No two-qubit link on ' + backendName + ' stayed under the CZ error ceiling of ' + czCeiling + '. Raise maxAcceptableCzError in Set Watchtower Parameters.');
}

links.sort(function (a, b) { return a.linkScore - b.linkScore; });
const best = links[0];
const median = links[Math.floor(links.length / 2)];

const HALF_PI = '1.5707963267948966';
const c = best.controlQubit;
const t = best.targetQubit;

const qasmLines = [
  'OPENQASM 3.0;',
  'include "stdgates.inc";',
  'qubit[' + nQubits + '] q;',
  'bit[2] c;',
  'rz(' + HALF_PI + ') q[' + c + '];',
  'sx q[' + c + '];',
  'rz(' + HALF_PI + ') q[' + c + '];',
  'rz(' + HALF_PI + ') q[' + t + '];',
  'sx q[' + t + '];',
  'rz(' + HALF_PI + ') q[' + t + '];',
  'cz q[' + c + '], q[' + t + '];',
  'rz(' + HALF_PI + ') q[' + t + '];',
  'sx q[' + t + '];',
  'rz(' + HALF_PI + ') q[' + t + '];',
  'c[0] = measure q[' + c + '];',
  'c[1] = measure q[' + t + '];'
];

const predicted = (1 - best.czError) * (1 - best.readoutErrorControl) * (1 - best.readoutErrorTarget);

return [{ json: {
  backendName: backendName,
  queueLength: backendInfo.queueLength,
  nQubits: nQubits,
  calibrationUpdatedAt: props.last_update_date || null,
  controlQubit: best.controlQubit,
  targetQubit: best.targetQubit,
  czError: best.czError,
  readoutErrorControl: best.readoutErrorControl,
  readoutErrorTarget: best.readoutErrorTarget,
  t1Control: best.t1Control,
  t2Control: best.t2Control,
  t1Target: best.t1Target,
  t2Target: best.t2Target,
  bestLinkScore: best.linkScore,
  medianLinkScore: median.linkScore,
  linksEvaluated: links.length,
  predictedCorrelation: predicted,
  qasm3Input: qasmLines.join('\n')
} }];

const results = $('Retrieve Job Results').first().json;
const pending = $input.first().json;

let counts = null;
if (Array.isArray(results.pubs) && results.pubs.length > 0 && results.pubs[0]) {
  counts = results.pubs[0].counts || null;
}
if (!counts) {
  counts = results.counts || (results.result && results.result.counts) || null;
}
if (!counts || typeof counts !== 'object') {
  throw new Error('Job ' + (results.jobId || 'unknown') + ' carried no measurement counts. Top level keys were: ' + Object.keys(results).join(', '));
}

const keys = Object.keys(counts);
let shotsSeen = 0;
for (const k of keys) {
  if (typeof counts[k] === 'number') { shotsSeen = shotsSeen + counts[k]; }
}
if (shotsSeen === 0) { throw new Error('Every measurement bucket came back empty.'); }

function bucket(pattern) {
  let total = 0;
  for (const k of keys) {
    if (k.replace(/[^01]/g, '') === pattern && typeof counts[k] === 'number') { total = total + counts[k]; }
  }
  return total;
}

function round4(v) { return (typeof v === 'number' && isFinite(v)) ? Math.round(v * 10000) / 10000 : null; }

const correlated = bucket('00') + bucket('11');
const antiCorrelated = bucket('01') + bucket('10');
const correlationScore = correlated / shotsSeen;
const predicted = Number(pending.predictedCorrelation);
const delta = isNaN(predicted) ? null : round4(correlationScore - predicted);

return [{ json: {
  runAt: pending.runAt,
  status: 'scored',
  backend: pending.backend,
  queueLength: pending.queueLength,
  controlQubit: pending.controlQubit,
  targetQubit: pending.targetQubit,
  czError: pending.czError,
  readoutErrorControl: pending.readoutErrorControl,
  readoutErrorTarget: pending.readoutErrorTarget,
  t1Control: pending.t1Control,
  t2Control: pending.t2Control,
  t1Target: pending.t1Target,
  t2Target: pending.t2Target,
  linksEvaluated: pending.linksEvaluated,
  calibrationUpdatedAt: pending.calibrationUpdatedAt,
  predictedCorrelation: isNaN(predicted) ? null : round4(predicted),
  requestedShots: pending.requestedShots,
  jobId: pending.jobId,
  qpuSecondsRemaining: pending.qpuSecondsRemaining,
  scoredAt: new Date().toISOString(),
  shots: shotsSeen,
  correlationScore: round4(correlationScore),
  deltaVsCalibration: delta,
  antiCorrelatedShots: antiCorrelated,
  rawCounts: JSON.stringify(counts)
} }];

const settings = $('Set Alert Configuration').first().json;
const today = $('Calculate Correlation Score').first().json;
const windowDays = Number(settings.historyWindowDays) || 14;
const cutoff = Date.now() - windowDays * 24 * 60 * 60 * 1000;

const rows = [];
for (const item of $input.all()) {
  const r = item.json || {};
  if (String(r.status || '') !== 'scored') { continue; }
  if (r.jobId && today.jobId && String(r.jobId) === String(today.jobId)) { continue; }
  const stamp = Date.parse(r.runAt);
  if (isNaN(stamp)) { continue; }
  if (stamp < cutoff) { continue; }
  rows.push({ stamp: stamp, row: r });
}
rows.sort(function (a, b) { return a.stamp - b.stamp; });

const scores = [];
for (const entry of rows) {
  const v = Number(entry.row.correlationScore);
  if (!isNaN(v)) { scores.push(v); }
}

let mean = null;
if (scores.length > 0) {
  let sum = 0;
  for (const v of scores) { sum = sum + v; }
  mean = sum / scores.length;
}

const lines = [];
for (const entry of rows.slice(-windowDays)) {
  const r = entry.row;
  lines.push(r.runAt + ' | ' + r.backend + ' | q' + r.controlQubit + '-q' + r.targetQubit + ' | correlation ' + r.correlationScore + ' | cz ' + r.czError + ' | predicted ' + r.predictedCorrelation);
}

function round4(v) { return (typeof v === 'number' && isFinite(v)) ? Math.round(v * 10000) / 10000 : null; }

return [{ json: {
  historyCount: rows.length,
  rollingMean: round4(mean),
  bestScore: scores.length ? Math.max.apply(null, scores) : null,
  worstScore: scores.length ? Math.min.apply(null, scores) : null,
  deltaVsRollingMean: (mean === null) ? null : round4(Number(today.correlationScore) - mean),
  historyTable: lines.length ? lines.join('\n') : 'No earlier scored runs inside the window yet.'
} }];

